import time, itertools, sys
n=10; N=30; M=57
edges=[]
for g in range(n):
    b=3*g
    edges += [(b,b+1),(b,b+2),(b+1,b+2)]
for g in range(n-1):
    for i in range(3): edges.append((3*g+i,3*(g+1)+i))
assert len(edges)==M
vid=0
def newvar():
    global vid
    vid+=1; return vid
X=[[newvar() for l in range(M+1)] for v in range(N)]
Y=[[newvar() for d in range(1,M+1)] for e in range(M)]
clauses=[]
def add_exactly_one(vars):
    clauses.append(vars[:])
    for i in range(len(vars)):
        vi=vars[i]
        for j in range(i+1,len(vars)):
            clauses.append([-vi,-vars[j]])
# vertex exactly one label
for v in range(N): add_exactly_one(X[v])
# label at most one vertex (not all labels used)
for l in range(M+1):
    for v1 in range(N):
        for v2 in range(v1+1,N): clauses.append([-X[v1][l],-X[v2][l]])
# edge y at most one (at least forced)
for e in range(M):
    ys=Y[e]
    for i in range(M):
        for j in range(i+1,M): clauses.append([-ys[i],-ys[j]])
# diff at most one edge
for d in range(1,M+1):
    lits=[Y[e][d-1] for e in range(M)]
    for i in range(M):
        for j in range(i+1,M): clauses.append([-lits[i],-lits[j]])
# assignment implies y diff
for e,(u,v) in enumerate(edges):
    for a in range(M+1):
        xu=X[u][a]
        for b in range(M+1):
            if a==b: continue
            clauses.append([-xu, -X[v][b], Y[e][abs(a-b)-1]])
# symmetry first clique sorted
for a in range(M+1):
    for b in range(M+1):
        if a>=b: clauses.append([-X[0][a],-X[1][b]])
        if a>=b: clauses.append([-X[1][a],-X[2][b]])
